  <style>
    /* ==========================================================================
       1. 殿堂级暗黑哥特 × 赛博灵能设计系统 (Grimoire HUD v2.0 Design Tokens)
       ========================================================================== */
    .dc-grimoire-v2 {
      --dc-bg-abyss: #050811;
      --dc-bg-glass: rgba(8, 14, 26, 0.85);
      --dc-bg-card: rgba(13, 22, 38, 0.75);
      --dc-bg-card-hover: rgba(20, 33, 56, 0.88);
      --dc-soul-emerald: #2ee6a8;
      --dc-soul-glow: rgba(46, 230, 168, 0.38);
      --dc-cyber-blue: #38bdf8;
      --dc-cyber-glow: rgba(56, 189, 248, 0.35);
      --dc-crimson-blood: #ff4d6a;
      --dc-crimson-glow: rgba(255, 77, 106, 0.4);
      --dc-sacred-gold: #f5c542;
      --dc-sacred-glow: rgba(245, 197, 66, 0.38);
      --dc-void-purple: #c084fc;
      --dc-void-glow: rgba(192, 132, 252, 0.4);
      --dc-border-gold: rgba(245, 197, 66, 0.22);
      --dc-border-cyan: rgba(56, 189, 248, 0.2);
      --dc-text-bright: #ffffff;
      --dc-text-main: #e2e8f0;
      --dc-text-sub: #94a3b8;
      --dc-text-muted: #64748b;

      box-sizing: border-box;
      width: 100%;
      margin: 1rem 0;
      color: var(--dc-text-main);
      font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Cinzel", "Noto Serif SC", serif, sans-serif;
      font-size: 14px;
      line-height: 1.5;
      -webkit-font-smoothing: antialiased;
    }

    .dc-grimoire-v2 * { box-sizing: border-box; margin: 0; padding: 0; }
    .dc-grimoire-v2 ::selection { background: var(--dc-soul-glow); color: #fff; }

    /* 全息手札总容器 */
    .dc-tome-v2 {
      position: relative;
      overflow: hidden;
      border: 1px solid var(--dc-border-gold);
      border-radius: 16px;
      background:
        radial-gradient(ellipse at 10% 0%, rgba(192, 132, 252, 0.12), transparent 40%),
        radial-gradient(ellipse at 90% 0%, rgba(56, 189, 248, 0.12), transparent 40%),
        radial-gradient(circle at 50% 100%, rgba(255, 77, 106, 0.08), transparent 50%),
        linear-gradient(175deg, #090e1a 0%, #05070d 60%, #070b14 100%);
      backdrop-filter: blur(20px) saturate(180%);
      -webkit-backdrop-filter: blur(20px) saturate(180%);
      box-shadow:
        0 20px 50px rgba(0, 0, 0, 0.75),
        inset 0 0 40px rgba(56, 189, 248, 0.03),
        inset 0 0 60px rgba(245, 197, 66, 0.02);
    }

    .dc-tome-v2::before {
      content: "";
      position: absolute;
      inset: 3px;
      pointer-events: none;
      border: 1px solid rgba(245, 197, 66, 0.12);
      border-radius: 13px;
    }

    /* 顶部视界状态栏 */
    .dc-top-bar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 0.9rem 1.25rem;
      border-bottom: 1px solid rgba(245, 197, 66, 0.18);
      background: linear-gradient(90deg, rgba(46, 230, 168, 0.05), rgba(192, 132, 252, 0.04) 50%, rgba(56, 189, 248, 0.05));
    }
    .dc-brand-group {
      display: flex;
      align-items: center;
      gap: 0.75rem;
    }
    .dc-lamp-core {
      position: relative;
      width: 1.1rem;
      height: 1.35rem;
      flex-shrink: 0;
      border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;
      background: radial-gradient(circle at 35% 30%, #e0fff7, var(--dc-soul-emerald) 60%, #064e3b 100%);
      box-shadow: 0 0 14px var(--dc-soul-emerald), 0 0 28px var(--dc-soul-glow);
      animation: dc-breathe-lamp 3.6s ease-in-out infinite;
    }
    @keyframes dc-breathe-lamp {
      0%, 100% { transform: scale(1); filter: brightness(1); }
      50% { transform: scale(1.08); filter: brightness(1.35) drop-shadow(0 0 8px var(--dc-soul-emerald)); }
    }
    .dc-title-main {
      font-size: 1.1rem;
