      letter-spacing: 0.04em;
    }

    /* 四大功能舱导航 */
    .dc-nav-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 2px;
      padding: 0.35rem 0.6rem;
