    }
    .dc-nav-btn:hover {
      color: var(--dc-text-bright);
      background: rgba(255, 255, 255, 0.04);
    }
    .dc-nav-btn[aria-selected="true"] {
      color: var(--dc-text-bright);
      background: linear-gradient(180deg, rgba(56, 189, 248, 0.14) 0%, rgba(8, 14, 26, 0.3) 100%);
      box-shadow: inset 0 0 16px rgba(56, 189, 248, 0.18), 0 2px 8px rgba(0, 0, 0, 0.4);
      border: 1px solid rgba(56, 189, 248, 0.35);
    }
    .dc-nav-btn[aria-selected="true"]::after {
      content: "";
